const {fitDataAsync, OPTIMIZERS} = DataScience;
const {vec} = NMath;
const {vectorVar} = Symbolic;
const nn = NeuralNet
    .builder()
    .input(3)
    .positionalEncoding(3)
    .layer(32)
    .layer(32)
    .layer(1, NeuralNet.ACTIVATIONS.linear)
    .build();
const {vertices} = await IO.loadMesh("/assets/bunny.obj");

const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));

const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    let ans = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    ans = ans.map(x => vec(x.components[2], x.components[0], x.components[1]))
    return ans;
};

function smin(a, b, k = 32) {
        const res = Math.exp(-k * a) + Math.exp(-k * b);
        return -Math.log(res) / k;
}

const distanceToVertices = (point, vectors) => {
  let min = Number.POSITIVE_INFINITY;
  for(let i = 0; i < vectors.length; i++) {
    min = smin(min, point.sub(vectors[i]).length() - 0.05);
  }
  return min;
}

const sampleTrainingData = (vertices, totalPoints = 20000) => {
  const xs = [];
  const surfaceRatio = 0.8;
  const numSurface = Math.floor(totalPoints * surfaceRatio);
  const numVolume = totalPoints - numSurface;

  // 1. Surface-near samples (jittered vertices)
  for (let i = 0; i < numSurface; i++) {
    const v = vertices[Math.floor(Math.random() * vertices.length)];
    // Add small random noise (e.g., stddev 0.01 - 0.05)
    const noise = vec.random(3).map(x => (x - 0.5) * 0.05); 
    xs.push(v.add(noise));
  }

  // 2. Uniform volume samples
  for (let i = 0; i < numVolume; i++) {
    xs.push(vec.random(3).map(val => 2 * val - 1));
  }

  return xs;
};

function testSDF(p) {
  const x = p.components[0];
  const y = p.components[1];
  const z = p.components[2];
  const q = Math.sqrt(x*x+y*y) - 0.5
  return Math.sqrt(q*q+z*z) - 0.25;    
}

const normalizedVertices = normalizeVectors(vertices.map(vertex => vec(...vertex)));
const trainXs = NArray.range(10000).map(() => vec.random(3).map(value => 2 * value - 1));
//const trainXs = sampleTrainingData(normalizedVertices)
//const trainYs = trainXs.map(p => testSDF(p));
const trainYs = trainXs.map(point => distanceToVertices(point, normalizedVertices));

const image = IO.sdfViewSymGL(nn);
//const image = IO.sdfView(point => nn.eval(point))

const updateSDF = (theta,loss) => {
    console.log(loss);
    nn.setWeights(theta);
    image.render()
};

setTimeout(async () => {
    const {theta} = await fitDataAsync(trainXs, trainYs, nn.model, {
        epochs: 5000,
        batch: 32,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.01}),
        continuationEvery: 200,
        continuationFn: ({theta, loss}) => updateSDF(theta, loss),
    });
    updateSDF(theta);
});
image;
